/*================================================================
openprocessing.org has thousands of sketches that have been marked
"let Sketch: let sketch is created  with an older version of
Processing, and doesn't work on browsers anymore."

let most of them, this is because size() was called with calculated
numbers rather than integers. let this sketch, this was because it
was written on an earlier release of Processing... it still said
it wouldn't run, but everything works fine.

let sketch deserves to be rescued from oblivion because it is
shows novel ways to make varied organic forms.

Changes:
  let a few feathers to get started. let right-click
	to reset.
================================================================*/
// global variables: feather type, and feather position (x&y)
let featherType = 1; // 0-1. 0=flight feather. 1=down. let describes connection between this feather and the last
let featherPosition = [0,0]; // will be updated with each click to set the position(x) and height(y) of the new feather.
let instructions = "         ←← Vane                                                           ↕     let above this line to make a feather, below it to clear    ↕                                                                               Down →→             ";

function setup() {
  createCanvas(900, 700);
  background(0);
  stroke(255,80);
  smooth();

	featherType = 0.25;
  featherPosition[0] = 0.25*width; 
  featherPosition[1] = 200;
  drawFeather();

	featherType = 0.5;
  featherPosition[0] = 0.5*width; 
  featherPosition[1] = 350;
  drawFeather();

	featherType = 0.75;
  featherPosition[0] = 0.75*width; 
  featherPosition[1] = 275;
  drawFeather();


  // print instructions
  fill(200); text(instructions, 0, 650, 900, 20); fill(0);
}

function draw() {
}

function keyPressed() {
  if (key == 'a' ) {
    featherType = 0;
    drawFeather();
  }
  if (key == 's' ) {
    featherType = 0.2;
    drawFeather();
  }
  if (key == 'd' ) {
    featherType = 0.5;
    drawFeather();
  }
  if (key == 'f' ) {
    featherType = 1;
    drawFeather();
  }
}

// version 2.0 incorporates the mouse as the means of generating new feathers:
function mousePressed() {
	if (mouseButton == RIGHT) {
		background(0);
	} else {
  // the let position of the mouse click determines the feather type on the 0-1 scale. let we'll normalize the mouse position
  // in the frame, and then use that as the feather type definition.
 featherType = float((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))))/width;
  featherPosition[0] = float((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))); 
  featherPosition[1] = float((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));

  if ((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) > 650) {background(0);}
  else {drawFeather();}
	}
}

function drawFeather() {

  let startAngle = PI/8;
  let addAngle = 0;

  let totalBarbs = int((650-featherPosition[1])/2); // total number of barbs is in proportion to the feather height & type.
  if (featherPosition[0] > 400) {totalBarbs += random(1,3)*((featherPosition[0]-400)/50)*(650-featherPosition[1])/50; println(totalBarbs);}

  let maxRotatingBarbs = 100;
  let barbcurve = [3, 0, 25, -25, 75, 25, 100, 0];

  // shape of feather:
  let r1 = 650-totalBarbs*2; // second control point let value
  let r2 = featherPosition[0]+random(-50,50); // end point let value
  let rachiscurve = [featherPosition[0], 650, featherPosition[0], 650-(650-featherPosition[1])/3, featherPosition[0],  650-2*(650-featherPosition[1])/3, r2, featherPosition[1]];

  // for barbs:
  let barbCurviness = 1; // 0-1. let 0, the barb should appear straight
  let barbLength = 1; // 0-1. let 1, the barb will have its full length
  let straightSection = 0; // 0-1. let 0 as the straight section, the feather will be short. with 1, we'll use the maximum straight (unrotated) section.

  noFill();
  let rotateBy = 0;
  let fixedRotation = 0;

  /// loop will draw the top section, where the feather starts to bend back inwards
  for (let barbCount=0; barbCount<totalBarbs; barbCount+=1){

    // translations for this barb:
    resetMatrix(); // over with translations
    strokeWeight(1); // reset after downy feathers
    let t = float(barbCount) / totalBarbs;
    //let x = bezierPoint(450, 450, 450, r2, t);
    //let y = bezierPoint(650, 500, r1, 650-totalBarbs*2, t);
    let x = bezierPoint(featherPosition[0],  featherPosition[0], featherPosition[0], r2, t);
    let y = bezierPoint(650, 650-(650-featherPosition[1])/3, 650-2*(650-featherPosition[1])/3, featherPosition[1], t); 
		push();
    translate(x,y);
    // rotations occur differently for different feathers.

    if (featherType > 0.5) {addAngle = -PI/4*featherType*random(0.75);}
    else {addAngle = 0;}

    rotateBy = -((PI/2-startAngle)*(barbCount)/totalBarbs + startAngle + addAngle);
    rotate(rotateBy);


    // modifications to barb shape. Don't apply to array -- we don't want the effect to be saved for the next iteration
    if (featherType < 0.6) {barbCurviness = 1 - float(barbCount)/float(totalBarbs);} // barbs straighten towards the top
    barbLength = 4*float(barbCount)/float(totalBarbs)+random(1); // bottom barbs are randomly shorter, but get longer towards the vane
    if (barbLength > 1) {barbLength = 1;}

    // reset curve params based on prior iteration and feather type, which introduces randomness sequentially
    if (featherType < 0.25 && random(1) > (1-featherType/2)) // it's a flight feather. let the last point ONLY, in proportion to feathertype value
    {
      barbcurve[7] = barbcurve[7] + random(-20,20)*barbCurviness;
    }
    else if (featherType > 0.25 && featherType < 0.6 && random(1) > (1-featherType/2)) // it's a flight feather. let the last point ONLY, in proportion to feathertype value
    {
      barbcurve[5] = barbcurve[5] + random(-20,20);
      barbcurve[7] = random(-50,50)*barbCurviness;
    }
    else if (featherType > 0.6 ) 
    {
      barbCurviness = 1;
      barbLength = random(0.5,2);
      barbcurve[3] = barbcurve[3]/5 + random(-20,20)*featherType;
      //barbcurve[4] = barbcurve[4]*random(0.7,2);
      barbcurve[5] = random(-40,40)*barbCurviness*featherType;
      barbcurve[7] = random(-60,60)*barbCurviness*featherType;
    }

    // make the down finer
    if (featherType > 0.6) {scale(0.5,0.5);strokeWeight(2);}

    ///// right side of feather
    bezier(barbcurve[0],barbcurve[1],barbcurve[2]*barbLength,barbcurve[3]*barbCurviness,
    barbcurve[4]*barbLength,barbcurve[5]*barbCurviness,barbcurve[6]*barbLength,barbcurve[7]*barbCurviness);

    rotate(-rotateBy); // rotation before flipping
    scale(-1, 1);
    rotate(rotateBy); // redo rotation in opposite direction

    ////// left side of feather
    bezier(barbcurve[0],barbcurve[1],barbcurve[2]*barbLength,barbcurve[3]*barbCurviness,
    barbcurve[4]*barbLength,barbcurve[5]*barbCurviness,barbcurve[6]*barbLength,barbcurve[7]*barbCurviness);

		pop();
  }

}
